/// Encode the by-notebook-or-by-cells selection choice for typed LSP output.
/// No external side effects or file/network I/O; takes input by value without borrowing caller state.
///
/// By-notebook and by-cells forms remain distinct, including absent versus empty cell lists; no
/// documents are selected here.
///
/// # Mapping
/// - `ByNotebook` stays `ByNotebook`; convert the payload through [`encode_notebook`],
///   [`encode_notebook_cell_selector`] in element order while preserving missing optional values.
/// - `ByCells` stays `ByCells`; convert the payload through [`encode_notebook`],
///   [`encode_notebook_cell_selector`] in element order while preserving missing optional values.
///
/// - `ByNotebook.notebook` uses [`encode_notebook`]; optional `cells` retain absence or convert each
///   language selector in order.
/// - `ByCells.notebook` is optional and uses [`encode_notebook`] only when present; required `cells`
///   convert each selector in order.
///
/// # Arguments
/// - `v` `[in]`: owned `d::NotebookSelector` consumed by conversion; no caller output storage.
/// # Returns
/// Always `Ok(value)` containing `lsp_types::NotebookSelector`. No output parameters or shared state
/// are changed.
///
/// # Algorithm
/// Select the input variant and rebuild the same output variant using the payload adapters above.
/// Containers are consumed rather than cloned.
/// # Flow
/// ```text
///           <input variant?>
///                   |
///           +-------+--------+
///           |                |
///     [ByNotebook]       [ByCells]
///           |                |
///     [map payload]    [map payload]
///           |                |
///           +-------+--------+
///                   |
///         [same output choice]
/// ```
/// # Examples
/// Private adapter context; this builds values only and does not send a message.
/// ```text
/// let input = d::NotebookSelector::ByNotebook {
///     notebook: d::Notebook::String("value".into()),
///     cells: None,
/// };
/// let output = encode_notebook_selector(input)?;
/// ```
pub(in crate::server::wrapper) fn encode_notebook_selector(
    v: d::NotebookSelector,
) -> Result<lsp_types::NotebookSelector, ServerError> {
    Ok::<_, ServerError>(match v {
        d::NotebookSelector::ByNotebook { notebook, cells } => {
            lsp_types::NotebookSelector::ByNotebook {
                notebook: encode_notebook(notebook)?,
                cells: (cells)
                    .map(|v| {
                        Ok::<_, ServerError>(
                            (v).into_iter()
                                .map(encode_notebook_cell_selector)
                                .collect::<Result<Vec<_>, ServerError>>()?,
                        )
                    })
                    .transpose()?,
            }
        }
        d::NotebookSelector::ByCells { notebook, cells } => lsp_types::NotebookSelector::ByCells {
            notebook: (notebook).map(encode_notebook).transpose()?,
            cells: (cells)
                .into_iter()
                .map(encode_notebook_cell_selector)
                .collect::<Result<Vec<_>, ServerError>>()?,
        },
    })
}
